"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[31549],{74169:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ToolGripService","desc":"When a player holds a Tool with moving parts (a Motor6D under its `Handle`),\\nthis turns the `RightGrip` Weld into a Motor6D with the same C0/C1. The\\nAnimator only reaches a joint through a chain of Motor6Ds from the\\ncharacter, so this lets the Fire / Reload animations (`WeaponAnims`) move\\nthe weapon parts. The Tool stays where `Tool.Grip` puts it.","realm":["Server"],"source":{"line":12,"path":"src/ServerScriptService/ToolGripService.server.luau"}}')}}]);